"use client"

// From chatcn, chat, voice and agent UI for shadcn: https://chatcn.dev

import * as React from "react"
import { forwardRef, createElement, type SVGAttributes, type ForwardRefExoticComponent, type RefAttributes } from "react"
import { cn } from "@/lib/utils"

/** chatcn theme variables and utilities this file uses, light and dark. */
const CHATCN_CSS = ":root{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-alpha-400:oklch(0 0 0 / 0.1);--chatcn-alpha-500:oklch(0 0 0 / 0.14);--chatcn-alpha-600:oklch(0 0 0 / 0.2);--chatcn-ease-out:cubic-bezier(0.23, 1, 0.32, 1);--chatcn-ease-out-soft:cubic-bezier(0.25, 0.46, 0.45, 0.94);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-fill-active:var(--chatcn-gray-300);--chatcn-gray-100:oklch(0.970 0 0);--chatcn-gray-1000:oklch(0.145 0 0);--chatcn-gray-300:oklch(0.930 0 0);--chatcn-gray-700:oklch(0.700 0 0);--chatcn-gray-800:oklch(0.525 0 0);--chatcn-gray-900:oklch(0.440 0 0);--chatcn-on-media:oklch(1 0 0);--chatcn-on-media-shadow:oklch(0 0 0 / 0.55);--chatcn-press-scale-icon:0.94;--chatcn-radius-lg:12px;--chatcn-radius-md:8px;--chatcn-radius-sm:6px;--chatcn-shadow-md:0 0 0 1px oklch(0 0 0 / 0.06), 0 2px 4px -1px oklch(0 0 0 / 0.06), 0 8px 16px -4px oklch(0 0 0 / 0.08);--chatcn-surface:oklch(1 0 0)}.dark{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-alpha-400:oklch(1 0 0 / 0.11);--chatcn-alpha-500:oklch(1 0 0 / 0.16);--chatcn-alpha-600:oklch(1 0 0 / 0.24);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-fill-active:var(--chatcn-gray-300);--chatcn-gray-100:oklch(0.195 0 0);--chatcn-gray-1000:oklch(0.970 0 0);--chatcn-gray-300:oklch(0.255 0 0);--chatcn-gray-700:oklch(0.500 0 0);--chatcn-gray-800:oklch(0.620 0 0);--chatcn-gray-900:oklch(0.720 0 0);--chatcn-on-media:oklch(1 0 0);--chatcn-on-media-shadow:oklch(0 0 0 / 0.55);--chatcn-shadow-md:0 0 0 1px oklch(1 0 0 / 0.09), inset 0 1px 0 oklch(1 0 0 / 0.04), 0 8px 16px -4px oklch(0 0 0 / 0.5);--chatcn-surface:oklch(0.205 0 0)}.chatcn-focus{}.chatcn-focus:focus-visible{outline: 2px solid var(--chatcn-accent); outline-offset: 2px;}"
if (typeof document !== "undefined" && !document.getElementById("chatcn-image-compare")) {
  const style = document.createElement("style")
  style.id = "chatcn-image-compare"
  style.textContent = CHATCN_CSS
  document.head.appendChild(style)
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export interface ImageCompareSource {
  src: string
  alt: string
}

export type ImageCompareOrientation = "horizontal" | "vertical"

/** `"3:2"`, `"9:16"`, or a number (width over height). */
export type ImageCompareAspectRatio = `${number}:${number}` | number

export interface ImageCompareProps
  extends Omit<React.ComponentProps<"div">, "defaultValue" | "onChange" | "children"> {
  /** Shown on the start side (or the top, when vertical). An image, or any node to fill it. */
  before: ImageCompareSource | React.ReactNode
  /** Shown on the end side (or the bottom). */
  after: ImageCompareSource | React.ReactNode
  /** Default "Original". */
  beforeLabel?: string
  /** Default "Edited". */
  afterLabel?: string
  /** Show the labels. They step aside when the handle comes close. Default true. */
  labels?: boolean
  /** How much of `before` shows, 0 to 100, from the start edge (or the top). */
  position?: number
  /** Default 50. */
  defaultPosition?: number
  onPositionChange?: (position: number) => void
  /** Fires once a drag, click or key press settles, for analytics or saving the position. */
  onPositionCommit?: (position: number) => void
  /** Default `horizontal`: a vertical divider moving left and right. */
  orientation?: ImageCompareOrientation
  /** Default 1. Set it from the images so the frame never shifts while they load. */
  aspectRatio?: ImageCompareAspectRatio
  disabled?: boolean
}

const clamp = (n: number) => Math.min(100, Math.max(0, n))

/** The click-to-jump glide. Drags and keys are instant. */
const JUMP_MS = 180

/** Pixels a touch must travel along the axis before it counts as a drag rather than a scroll. */
const TOUCH_SLOP = 6

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

function parseRatio(ratio: ImageCompareAspectRatio | undefined): number {
  if (typeof ratio === "number") return ratio > 0 ? ratio : 1
  if (!ratio) return 1
  const [w, h] = ratio.split(":").map(Number)
  return w && h && w > 0 && h > 0 ? w / h : 1
}

const isSource = (value: unknown): value is ImageCompareSource =>
  typeof value === "object" &&
  value !== null &&
  !React.isValidElement(value) &&
  typeof (value as ImageCompareSource).src === "string"

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

const iconNode: IconNode = [
  ["path", {"d":"m3.5 3.5 17 17"}],
  ["path", {"d":"M6.64 3H18a3 3 0 0 1 3 3v11.36"}],
  ["path", {"d":"M17.36 21H6a3 3 0 0 1-3-3V6.64"}],
  ["path", {"d":"M13.75 8.5a1.75 1.75 0 1 0 3.5 0 1.75 1.75 0 1 0-3.5 0"}],
  ["path", {"d":"m6.25 18 1.94-1.94a1.5 1.5 0 0 1 2.12 0L12.25 18"}],
]

const ImageOffIcon: Icon = /* @__PURE__ */ createIcon("image-off", iconNode)

/* -------------------------------------------------------------------------------------------------
 * Layer
 * -----------------------------------------------------------------------------------------------*/

function CompareLayer({
  content,
  className,
  style,
  slot,
  visible,
}: {
  content: ImageCompareSource | React.ReactNode
  className?: string
  style?: React.CSSProperties
  slot: string
  /** The part of the frame this layer shows, so a fallback centres where it can be seen. */
  visible?: React.CSSProperties
}) {
  const src = isSource(content) ? content.src : undefined
  const [state, setState] = React.useState<{ src?: string; ok: boolean | null }>({ src, ok: null })
  if (state.src !== src) setState({ src, ok: null })
  const ref = React.useCallback(
    (img: HTMLImageElement | null) => {
      if (img?.complete && img.naturalWidth > 0) {
        setState((s) => (s.src === src && s.ok !== true ? { src, ok: true } : s))
      }
    },
    [src],
  )

  return (
    <div data-slot={slot} className={cn("absolute inset-0", className)} style={style}>
      {isSource(content) ? (
        <>
          <img
            ref={ref}
            src={content.src}
            alt={content.alt}
            draggable={false}
            decoding="async"
            onLoad={() => setState((s) => (s.ok === true ? s : { src, ok: true }))}
            onError={() => setState({ src, ok: false })}
            className={cn(
              "absolute inset-0 size-full object-cover select-none",
              "ease-(--chatcn-ease-out-soft) transition-opacity duration-200",
              state.ok ? "opacity-100" : "opacity-0",
            )}
          />
          {state.ok === false ? (
            <span
              style={visible}
              className="text-(color:--chatcn-fg-subtle) absolute inset-0 flex flex-col items-center justify-center gap-2 overflow-hidden p-3 text-center"
            >
              <ImageOffIcon aria-hidden="true" className="size-5" />
              <span className="text-[0.75rem]/[1rem]">Image unavailable</span>
            </span>
          ) : null}
        </>
      ) : (
        content
      )}
    </div>
  )
}

/* -------------------------------------------------------------------------------------------------
 * ImageCompare
 * -----------------------------------------------------------------------------------------------*/

/** Label chips sit on imagery, so they use the fixed on-media pair instead of theme grays. */
const LABEL =
  "text-[0.75rem]/[1rem] bg-(color:--chatcn-on-media-shadow) text-(color:--chatcn-on-media) pointer-events-none absolute inline-flex h-6 items-center rounded-full px-2 font-medium whitespace-nowrap backdrop-blur-sm ease-(--chatcn-ease-out) transition-opacity duration-150 forced-colors:border"

const iconNode2: IconNode = [
  ["path", {"d":"M8.4 5.5a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
  ["path", {"d":"M14.4 5.5a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
  ["path", {"d":"M8.4 12a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
  ["path", {"d":"M14.4 12a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
  ["path", {"d":"M8.4 18.5a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
  ["path", {"d":"M14.4 18.5a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
]

const GripVerticalIcon: Icon = /* @__PURE__ */ createIcon("grip-vertical", iconNode2)

const iconNode3: IconNode = [
  ["path", {"d":"M4.9 9a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
  ["path", {"d":"M4.9 15a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
  ["path", {"d":"M11.4 9a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
  ["path", {"d":"M11.4 15a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
  ["path", {"d":"M17.9 9a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
  ["path", {"d":"M17.9 15a.6.6 0 1 0 1.2 0 .6.6 0 1 0-1.2 0"}],
]

const GripHorizontalIcon: Icon = /* @__PURE__ */ createIcon("grip-horizontal", iconNode3)

/**
 * Before and after, one over the other, split by a draggable hairline. Drag the grip or anywhere
 * on the image, click to jump, or focus the grip and use the arrow keys.
 */
export function ImageCompare({
  before,
  after,
  beforeLabel = "Original",
  afterLabel = "Edited",
  labels = true,
  position: positionProp,
  defaultPosition = 50,
  onPositionChange,
  onPositionCommit,
  orientation = "horizontal",
  aspectRatio = 1,
  disabled = false,
  className,
  style,
  onPointerDown,
  ...props
}: ImageCompareProps) {
  const horizontal = orientation === "horizontal"
  const rootRef = React.useRef<HTMLDivElement>(null)
  const gripRef = React.useRef<HTMLDivElement>(null)
  const beforeLabelRef = React.useRef<HTMLSpanElement>(null)
  const afterLabelRef = React.useRef<HTMLSpanElement>(null)

  const [positionState, setPositionState] = React.useState(clamp(defaultPosition))
  const position = clamp(positionProp ?? positionState)
  const latest = React.useRef(position)
  latest.current = position
  const setPosition = (next: number) => {
    const value = Math.round(clamp(next) * 100) / 100
    if (value === latest.current) return
    latest.current = value
    if (positionProp === undefined) setPositionState(value)
    onPositionChange?.(value)
  }

  // Direction and size, measured: logical properties cannot express a clip from the end edge.
  const [rtl, setRtl] = React.useState(false)
  const [size, setSize] = React.useState({ w: 0, h: 0, before: 0, after: 0 })
  React.useLayoutEffect(() => {
    const root = rootRef.current
    if (!root) return
    const measure = () => {
      setRtl(getComputedStyle(root).direction === "rtl")
      const rect = root.getBoundingClientRect()
      const extent = (el: HTMLElement | null) =>
        el ? (horizontal ? el.offsetWidth : el.offsetHeight) : 0
      setSize({
        w: rect.width,
        h: rect.height,
        before: extent(beforeLabelRef.current),
        after: extent(afterLabelRef.current),
      })
    }
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(root)
    return () => observer.disconnect()
  }, [horizontal])

  // The click-to-jump glide is the only animated move.
  const [gliding, setGliding] = React.useState(false)
  React.useEffect(() => {
    if (!gliding) return
    const id = window.setTimeout(() => setGliding(false), JUMP_MS + 20)
    return () => window.clearTimeout(id)
  }, [gliding])

  const fromPointer = (event: { clientX: number; clientY: number }) => {
    const rect = rootRef.current?.getBoundingClientRect()
    if (!rect || rect.width === 0 || rect.height === 0) return latest.current
    const r = horizontal
      ? (event.clientX - rect.left) / rect.width
      : (event.clientY - rect.top) / rect.height
    return clamp((horizontal && rtl ? 1 - r : r) * 100)
  }

  const gesture = React.useRef<{
    id: number
    x: number
    y: number
    dragging: boolean
    touch: boolean
  } | null>(null)

  const handlePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerDown?.(event)
    if (disabled || event.defaultPrevented || event.button !== 0) return
    const onGrip = gripRef.current?.contains(event.target as Node) ?? false
    const touch = event.pointerType !== "mouse"
    gesture.current = {
      id: event.pointerId,
      x: event.clientX,
      y: event.clientY,
      dragging: !touch,
      touch,
    }
    event.currentTarget.setPointerCapture?.(event.pointerId)
    // Keep focus on the grip, so arrow keys work right after a click.
    event.preventDefault()
    gripRef.current?.focus({ preventScroll: true })
    setKeyed(false)
    if (!touch) setDragging(true)
    if (!touch && !onGrip) {
      setGliding(true)
      setPosition(fromPointer(event))
    }
  }

  const handlePointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const g = gesture.current
    if (!g || g.id !== event.pointerId) return
    if (!g.dragging) {
      const along = horizontal ? event.clientX - g.x : event.clientY - g.y
      if (Math.abs(along) < TOUCH_SLOP) return
      g.dragging = true
      setDragging(true)
    }
    setGliding(false)
    setPosition(fromPointer(event))
  }

  const endGesture = (event: React.PointerEvent<HTMLDivElement>, cancelled: boolean) => {
    const g = gesture.current
    if (!g || g.id !== event.pointerId) return
    gesture.current = null
    setDragging(false)
    if (cancelled) return
    // A tap on touch screens: jump there, like a click.
    if (g.touch && !g.dragging) {
      setGliding(true)
      setPosition(fromPointer(event))
    }
    onPositionCommit?.(latest.current)
  }

  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return
    const step = event.shiftKey ? 10 : 1
    // Keys follow what you see: the handle moves in the arrow's direction.
    const toward = rtl && horizontal ? -1 : 1
    const deltas: Record<string, number> = horizontal
      ? { ArrowRight: step * toward, ArrowLeft: -step * toward, ArrowUp: step, ArrowDown: -step }
      : { ArrowDown: step, ArrowUp: -step, ArrowRight: step, ArrowLeft: -step }
    let next: number | undefined
    if (event.key in deltas) next = latest.current + (deltas[event.key] ?? 0)
    else if (event.key === "PageUp") next = latest.current + 10
    else if (event.key === "PageDown") next = latest.current - 10
    else if (event.key === "Home") next = 0
    else if (event.key === "End") next = 100
    if (next === undefined) return
    event.preventDefault()
    setKeyed(true)
    setGliding(false)
    setPosition(next)
  }

  const onKeyUp = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (/^(Arrow|Page|Home|End)/.test(event.key)) onPositionCommit?.(latest.current)
  }

  // Labels step aside when the handle is within their width plus a margin.
  const extent = horizontal ? size.w : size.h
  const at = (position / 100) * extent
  const margin = 24
  const hideBefore = extent > 0 && at < size.before + margin
  const hideAfter = extent > 0 && extent - at < size.after + margin

  const rest = 100 - position
  const clip = horizontal
    ? rtl
      ? `inset(0 0 0 ${rest}%)`
      : `inset(0 ${rest}% 0 0)`
    : `inset(0 0 ${rest}% 0)`
  const shift = horizontal
    ? `translateX(${rtl ? -position : position}%)`
    : `translateY(${position}%)`
  const glide = gliding ? "ease-(--chatcn-ease-out) duration-180 motion-reduce:duration-0" : "duration-0"
  const rounded = Math.round(position)

  // Where each side shows, so an "Image unavailable" fallback centres in its visible part.
  const beforeVisible: React.CSSProperties = horizontal
    ? { insetInlineEnd: `${rest}%` }
    : { bottom: `${rest}%` }
  const afterVisible: React.CSSProperties = horizontal
    ? { insetInlineStart: `${position}%` }
    : { top: `${position}%` }

  // The value shows while the handle is in use: a drag, or keyboard focus.
  const [dragging, setDragging] = React.useState(false)
  const [keyed, setKeyed] = React.useState(false)
  const readout = !disabled && (dragging || keyed)

  return (
    // The surface takes pointer input; the grip inside is the keyboard-operable slider.
    <div
      ref={rootRef}
      data-slot="image-compare"
      data-orientation={orientation}
      data-disabled={disabled ? "" : undefined}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={(event) => endGesture(event, false)}
      onPointerCancel={(event) => endGesture(event, true)}
      className={cn(
        "bg-(color:--chatcn-fill) rounded-(--chatcn-radius-lg) relative isolate w-full overflow-hidden select-none",
        "[-webkit-tap-highlight-color:transparent]",
        horizontal ? "cursor-ew-resize touch-pan-y" : "cursor-ns-resize touch-pan-x",
        disabled && "cursor-default",
        className,
      )}
      style={{ aspectRatio: parseRatio(aspectRatio), ...style }}
      {...props}
    >
      <CompareLayer slot="image-compare-after" content={after} visible={afterVisible} />
      <CompareLayer
        slot="image-compare-before"
        content={before}
        visible={beforeVisible}
        className={cn("transition-[clip-path]", glide)}
        style={{ clipPath: clip }}
      />

      {labels ? (
        <>
          <span
            ref={beforeLabelRef}
            aria-hidden="true"
            data-slot="image-compare-label"
            className={cn(LABEL, "start-3 top-3", hideBefore && "opacity-0")}
          >
            {beforeLabel}
          </span>
          <span
            ref={afterLabelRef}
            aria-hidden="true"
            data-slot="image-compare-label"
            className={cn(
              LABEL,
              horizontal ? "end-3 top-3" : "start-3 bottom-3",
              hideAfter && "opacity-0",
            )}
          >
            {afterLabel}
          </span>
        </>
      ) : null}

      {/* The handle travels on a full-size track, so it moves with transform only. */}
      <div
        aria-hidden={disabled || undefined}
        className={cn("pointer-events-none absolute inset-0 transition-transform", glide)}
        style={{ transform: shift }}
      >
        <span
          className={cn(
            "bg-(color:--chatcn-on-media) absolute shadow-[0_0_0_0.5px_var(--chatcn-alpha-500),0_0_6px_var(--chatcn-alpha-600)]",
            horizontal
              ? "inset-y-0 start-0 w-px -translate-x-1/2 rtl:translate-x-1/2"
              : "inset-x-0 top-0 h-px -translate-y-1/2",
          )}
        />
        <div
          ref={gripRef}
          role="slider"
          tabIndex={disabled ? -1 : 0}
          aria-label={`Compare ${beforeLabel.toLowerCase()} and ${afterLabel.toLowerCase()}`}
          aria-orientation={orientation}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={rounded}
          aria-valuetext={`${beforeLabel} ${rounded}%, ${afterLabel.toLowerCase()} ${100 - rounded}%`}
          aria-disabled={disabled || undefined}
          data-slot="image-compare-handle"
          onKeyDown={onKeyDown}
          onKeyUp={onKeyUp}
          onFocus={(event) => setKeyed(event.currentTarget.matches(":focus-visible"))}
          onBlur={() => setKeyed(false)}
          className={cn(
            "chatcn-focus bg-(color:--chatcn-surface) text-(color:--chatcn-fg-muted) shadow-(--chatcn-shadow-md) rounded-(--chatcn-radius-sm) pointer-events-auto absolute grid place-items-center",
            "ease-(--chatcn-ease-out) transition-[scale] duration-150 active:scale-(--chatcn-press-scale-icon) active:duration-100",
            // 24 px to see, 40 px to hit, 44 px on touch screens.
            "before:absolute before:-inset-2 before:content-[''] pointer-coarse:before:-inset-2.5",
            horizontal
              ? "start-0 top-1/2 h-7 w-5 -translate-x-1/2 -translate-y-1/2 rtl:translate-x-1/2"
              : "start-1/2 top-0 h-5 w-7 -translate-x-1/2 -translate-y-1/2 rtl:translate-x-1/2",
            disabled && "opacity-0",
          )}
        >
          {horizontal ? (
            <GripVerticalIcon aria-hidden="true" className="size-3.5" />
          ) : (
            <GripHorizontalIcon aria-hidden="true" className="size-3.5" />
          )}
          {/* The value, beside the grip while it is in use: how much of each side shows. */}
          <span
            aria-hidden="true"
            data-slot="image-compare-value"
            data-visible={readout ? "" : undefined}
            className={cn(
              LABEL,
              "tabular-nums",
              horizontal
