"use client"

import * as React from "react"
import { ImageCompare } from "@/components/ui/image-compare"

/** The preview opens partway through the first sweep, so the first frame is already moving. */
const START_MS = 380

/** How long a choice holds a tour before it carries on. */
const RESUME_MS = 1800

/** True until `RESUME_MS` after the last `hold()`, for tours with their own state. */
function useHold() {
  const [held, setHeld] = React.useState(false)
  const timer = React.useRef(0)
  React.useEffect(() => () => window.clearTimeout(timer.current), [])
  const hold = React.useCallback(() => {
    setHeld(true)
    window.clearTimeout(timer.current)
    timer.current = window.setTimeout(() => setHeld(false), RESUME_MS)
  }, [])
  return [held, hold] as const
}

const reducedMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches

/**
 * One edit on screen: the divider sweeps toward the start, then back past the middle, then the
 * next edit cuts in. Each leg settles quickly, so every second shows a different split.
 */
const SWEEP_MS = 1150

const REST_MS = 350

const EDIT_MS = 2 * (SWEEP_MS + REST_MS)

interface Edit {
  id: string
  title: string
  instruction: string
  photo: { src: string; alt: string }
  /** How the photo looked before the edit, drawn from the edited one with a CSS filter. */
  filter: string
  beforeLabel: string
  afterLabel: string
  beforeAlt: string
}

// picsum.photos id 823, 640 x 800, inline so the 21st preview needs no image host.
const beanie = {
  alt: "A woman in a red beanie raising a film camera to her eye in a forest",
  width: 640,
  height: 800,
  src: "data:image/webp;base64,",
}

// Unsplash 1431576901776, 720 x 540, inline so the 21st preview needs no image host.
const tower = {
  alt: "Two glass towers glowing orange, seen from below",
  width: 720,
  height: 540,
  src: "data:image/webp;base64,",
}

// picsum.photos id 599, 800 x 600, inline so the 21st preview needs no image host.
const summit = {
  alt: "A mountain summit rising above a sea of low clouds",
  width: 800,
  height: 600,
  src: "data:image/webp;base64,",
}

/** Three edits from one session, each shown against the photo it started from. */
const EDITS: Edit[] = [
  {
    id: "colorize",
    title: "Colorize",
    instruction: "Restore natural color to this scan. Keep the film grain.",
    photo: beanie,
    filter: "grayscale(1) contrast(1.12) brightness(1.04)",
    beforeLabel: "Scan",
    afterLabel: "Colorized",
    beforeAlt: "The same photo as a black and white scan",
  },
  {
    id: "relight",
    title: "Relight",
    instruction: "Make the glass glow like the sun just hit it.",
    photo: tower,
    filter: "saturate(0.15) brightness(0.62) contrast(1.05)",
    beforeLabel: "Overcast",
    afterLabel: "Relit",
    beforeAlt: "The same towers under a flat gray sky",
  },
  {
    id: "dehaze",
    title: "Clear haze",
    instruction: "Cut the haze on the peak. Keep the low cloud.",
    photo: summit,
    filter: "contrast(0.55) brightness(1.28) saturate(0.35) blur(0.6px)",
    beforeLabel: "Hazy",
    afterLabel: "Cleared",
    beforeAlt: "The same summit washed out by haze",
  },
]

const FROM = 78

const TO = 20

const ease = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2)

const BACK = 64

function positionAt(local: number) {
  if (local < SWEEP_MS) return FROM + (TO - FROM) * ease(local / SWEEP_MS)
  if (local < SWEEP_MS + REST_MS) return TO
  const t = (local - SWEEP_MS - REST_MS) / SWEEP_MS
  if (t < 1) return TO + (BACK - TO) * ease(t)
  return BACK
}

const FIT_CSS = "html,body{overflow:hidden}[data-fit-small] [data-fit-hide]{display:none!important}"

/**
 * 21st shows a demo in a small frame: about 674 by 421 on a component page, 358 by 224 on a
 * phone and 245 by 139 on a profile card. A demo taller than its frame gets scrollbars, which
 * render white on dark pages. FitFrame fills the frame exactly instead.
 *
 * - "scale": the content shrinks until it fits, centered. For visuals such as orbs.
 * - "crop": the content stays at full size from the top and fades out at the bottom. For text
 *   that streams in, where a changing scale would make the page breathe.
 *
 * `minWidth` lays out a wide demo (a table, a two column panel) at that width and scales it down
 * to the frame, instead of letting it collapse to a narrow layout. The frame centers it, so it
 * shrinks evenly on both sides.
 *
 * Anything marked `data-fit-hide` (state buttons, the chatcn.dev line) drops out in frames
 * shorter than `hideBelow`, so a profile card shows the visual alone.
 */
function FitFrame({
  children,
  mode = "scale",
  hideBelow = 360,
  minWidth,
}: {
  children: React.ReactNode
  mode?: "scale" | "crop"
  hideBelow?: number
  minWidth?: string
}) {
  const content = React.useRef<HTMLDivElement>(null)
  const [cropped, setCropped] = React.useState(false)

  React.useLayoutEffect(() => {
    const el = content.current
    if (!el) return
    const measure = () => {
      const vw = window.innerWidth
      const vh = window.innerHeight
      el.toggleAttribute("data-fit-small", vh < hideBelow)
      // Layout sizes ignore the transform, so measuring never feeds back.
      const w = Math.max(el.offsetWidth, el.scrollWidth)
      const h = Math.max(el.offsetHeight, el.scrollHeight)
      const scale = mode === "scale" ? Math.min(1, vw / w, vh / h) : 1
      el.style.transform = scale < 1 ? `scale(${scale})` : ""
      setCropped(mode === "crop" && h > vh + 1)
    }
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(el)
    // Content that changes inside a fixed width box (a headline that cycles words) never resizes
    // the box itself, so changes below it measure again on the next frame.
    let frame = 0
    const mutations = new MutationObserver(() => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(measure)
    })
    mutations.observe(el, { subtree: true, childList: true, characterData: true })
    window.addEventListener("resize", measure)
    return () => {
      observer.disconnect()
      mutations.disconnect()
      cancelAnimationFrame(frame)
      window.removeEventListener("resize", measure)
    }
  }, [mode, hideBelow])

  const fade = "linear-gradient(to bottom, #000 calc(100% - 40px), transparent)"
  return (
    <div
      className="flex w-full justify-center overflow-hidden"
      style={{
        height: "100dvh",
        alignItems: mode === "crop" ? "flex-start" : "center",
        maskImage: cropped ? fade : undefined,
        WebkitMaskImage: cropped ? fade : undefined,
      }}
    >
      <style>{FIT_CSS}</style>
      <div
        ref={content}
        className="w-full shrink-0"
        style={{ transformOrigin: mode === "crop" ? "top center" : "center", minWidth }}
      >
        {children}
      </div>
    </div>
  )
}

/** The line under each 21st demo that points back to the kit. */
function MoreOn({ slug, children }: { slug: string; children: React.ReactNode }) {
  return (
    <p data-fit-hide className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-faint) text-center text-balance">
      {children}{" "}
      <a
        href={`https://chatcn.dev/docs/components/${slug}`}
        target="_blank"
        rel="noopener"
        className="text-(color:--chatcn-fg-subtle) hover:text-(color:--chatcn-fg) underline underline-offset-2"
      >
        chatcn.dev
      </a>
    </p>
  )
}

/**
 * A photo editor's history: colorize a scan, relight two towers, clear the haze off a summit.
 * The divider sweeps across each result on its own, so the labels step aside as it passes. Drag
 * it or pick an edit and the tour waits a moment, then carries on.
 */
export default function ImageComparePreview() {
  const [clock, setClock] = React.useState(START_MS)
  const [held, hold] = useHold()
  const [mine, setMine] = React.useState({ edit: 0, position: 50 })

  React.useEffect(() => {
    if (held) return
    if (reducedMotion()) {
      setClock(SWEEP_MS * 2 + REST_MS)
      return
    }
    const began = performance.now() - clock
    let frame = 0
    const tick = () => {
      setClock(performance.now() - began)
      frame = requestAnimationFrame(tick)
    }
    frame = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(frame)
    // biome-ignore lint/correctness/useExhaustiveDependencies: resumes from the clock it held at.
  }, [held])

  const tourEdit = Math.floor(clock / EDIT_MS) % EDITS.length
  const editIndex = held ? mine.edit : tourEdit
  const edit = EDITS[editIndex]!
  const position = held ? mine.position : positionAt(clock % EDIT_MS)

  // Back on tour, the picked edit plays from the start of its sweep.
  const pick = (index: number) => {
    hold()
    setMine({ edit: index, position })
    setClock(index * EDIT_MS)
  }

  return (
    <FitFrame minWidth="38rem">
      <div className="flex w-full flex-col items-center justify-center gap-6 p-8">
        <div className="flex w-full max-w-2xl items-center justify-center gap-8">
          <ImageCompare
            className="w-auto shrink-0"
            style={{ height: "21rem" }}
            aspectRatio="4:5"
            position={position}
            onPositionChange={(next) => {
              hold()
              setMine({ edit: editIndex, position: next })
            }}
            onPointerDown={() => {
              hold()
              setMine({ edit: editIndex, position })
            }}
            before={
              <img
                src={edit.photo.src}
                alt={edit.beforeAlt}
                draggable={false}
                className="absolute inset-0 size-full object-cover select-none"
                style={{ filter: edit.filter }}
              />
            }
            after={{ src: edit.photo.src, alt: edit.photo.alt }}
            beforeLabel={edit.beforeLabel}
            afterLabel={edit.afterLabel}
          />
          <div data-fit-hide className="flex w-60 min-w-0 flex-col gap-3">
            <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) font-medium">Edits</p>
            <ol className="flex flex-col gap-1">
              {EDITS.map((e, i) => {
                const active = i === editIndex
                return (
                  <li key={e.id}>
                    <button
                      type="button"
                      aria-pressed={active}
                      onClick={() => pick(i)}
                      className="hover:bg-(color:--chatcn-fill) aria-pressed:bg-(color:--chatcn-fill-active) rounded-(--chatcn-radius-md) flex w-full flex-col gap-0.5 px-3 py-2 text-start transition-colors"
                    >
                      <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) flex items-center gap-2 font-medium">
                        <span className="text-(color:--chatcn-fg-faint) tabular-nums">{i + 1}</span>
                        {e.title}
                      </span>
                      <span
                        className={`text-[0.75rem]/[1rem] text-pretty ${active ? "text-(color:--chatcn-fg-muted)" : "text-(color:--chatcn-fg-subtle)"}`}
                      >
                        {e.instruction}
                      </span>
                    </button>
                  </li>
                )
              })}
            </ol>
          </div>
        </div>
        <MoreOn slug="image-compare">Drag, click or use the arrow keys to compare. On</MoreOn>
      </div>
    </FitFrame>
  )
}
